_BASE = {
    "config_schema": {}, "default_config": {"tasks.max": "1"}, "default_transforms": [], "version": "v1", "is_active": True,
    # Compatibility-contract defaults — overridden per-row above where a
    # template's own qualification data differs (connector_plugin,
    # connector_version, supported_source_versions, migration_notes).
    #
    # These are Confluent Platform's own version numbers (what
    # KafkaConnectClient.get_worker_info() actually reads off a live
    # worker's GET / response, e.g. "7.6.0-ccs" — see
    # app/services/deploy_preflight.py's _major_minor), not the bundled
    # Apache Kafka version — the two numbering schemes are unrelated (CP
    # 7.6 bundles Apache Kafka 3.6 internally, but never reports "3.6"
    # itself). The previous value here ("3.6"/"3.7"/"3.8") was Apache
    # Kafka's own numbering, which every worker this app's own
    # infra/docker-compose.yml provisions (confluentinc/cp-kafka-connect
    # 7.6.0) could never actually match — every single deploy failed this
    # check identically regardless of connector type, not just one
    # template (FE-BUG-25's stuck-pipeline investigation). A small window
    # around the pinned 7.6.0, not just that one exact version, so a minor
    # Confluent Platform upgrade doesn't immediately re-break every deploy.
    "supported_kafka_connect_versions": ["7.4", "7.5", "7.6", "7.7","7.8","7.9"],
    "config_schema_version": "1.0",
    "transform_compatibility": {},
    "migration_notes": None,
}

# The Single Message Transforms (SMTs) the platform supports, with a friendly blurb.
# Each SMT carries `params`: the config inputs shown per pipeline when the transform
# is applied. `type` is text | list (comma-separated fields) | select. The field the
# transform acts on is the first param (e.g. MaskField.fields, ExtractField.field).
# Kafka Connect turns each into `transforms.<name>.<key>` (see transform_policy.py).
SMT_LIB = {
    "ValueToKey": {"scope": "value", "description": "Set the record key from value field(s)",
                   "params": [{"key": "fields", "label": "Field(s) to copy into the key", "type": "list", "required": True, "placeholder": "id, tenant_id"}]},
    "ExtractField": {"scope": "value", "description": "Extract a single field as the whole record",
                     "params": [{"key": "field", "label": "Field to extract", "type": "text", "required": True, "placeholder": "id"}]},
    "HoistField": {"scope": "value", "description": "Wrap the record in a named field",
                   "params": [{"key": "field", "label": "Wrapper field name", "type": "text", "required": True, "placeholder": "payload"}]},
    "Flatten": {"scope": "value", "description": "Flatten nested structures using a delimiter",
                "params": [{"key": "delimiter", "label": "Delimiter", "type": "text", "required": False, "default": ".", "placeholder": "."}]},
    "RegexRouter": {"scope": "value", "description": "Rename/route the topic via a regex",
                    "params": [{"key": "regex", "label": "Topic regex", "type": "text", "required": True, "placeholder": "(.*)"},
                               {"key": "replacement", "label": "Replacement", "type": "text", "required": True, "placeholder": "prefixed_$1"}]},
    "HeaderFrom": {"scope": "value", "description": "Move or copy fields into record headers",
                   "params": [{"key": "fields", "label": "Field(s) to take", "type": "list", "required": True, "placeholder": "tenant_id"},
                              {"key": "headers", "label": "Header name(s)", "type": "list", "required": True, "placeholder": "x-tenant"},
                              {"key": "operation", "label": "Operation", "type": "select", "required": True, "default": "copy", "options": ["copy", "move"]}]},
    "MaskField": {"scope": "value", "description": "Mask field values (PII)",
                  "params": [{"key": "fields", "label": "Field(s) to mask", "type": "list", "required": True, "placeholder": "email, ssn"},
                             {"key": "replacement", "label": "Replace with (optional)", "type": "text", "required": False, "placeholder": "****"}]},
    "ReplaceField": {"scope": "value", "description": "Rename, include, or drop fields",
                     "params": [{"key": "exclude", "label": "Field(s) to drop", "type": "list", "required": False, "placeholder": "password, ssn"},
                                {"key": "renames", "label": "Renames (old:new, …)", "type": "list", "required": False, "placeholder": "fname:first_name"}]},
    "InsertField": {"scope": "value", "description": "Insert a static or metadata field",
                    "params": [{"key": "static.field", "label": "New field name", "type": "text", "required": True, "placeholder": "source_system"},
                               {"key": "static.value", "label": "Static value", "type": "text", "required": True, "placeholder": "salesforce"}]},
    "TimestampConverter": {"scope": "value", "description": "Convert timestamp field formats",
                           "params": [{"key": "field", "label": "Timestamp field", "type": "text", "required": True, "placeholder": "created_at"},
                                      {"key": "target.type", "label": "Target type", "type": "select", "required": True, "default": "string", "options": ["string", "unix", "Date", "Time", "Timestamp"]},
                                      {"key": "format", "label": "Format (when target is string)", "type": "text", "required": False, "default": "yyyy-MM-dd HH:mm:ss",
                                       # Required only for a string target: Kafka Connect fails the task without it.
                                       "required_when": {"key": "target.type", "value": "string"}, "placeholder": "yyyy-MM-dd HH:mm:ss"}]},
    "ExtractNewRecordState": {"scope": "value", "description": "Unwrap Debezium CDC envelope → flat row (needed before field transforms on CDC data)",
                              "params": [{"key": "delete.handling.mode", "label": "On delete", "type": "select", "required": False, "default": "rewrite", "options": ["rewrite", "drop", "none"]}]},
}

# Curated set of SMTs supported per connector family (editable in the DB afterwards).
def _transforms_for(category: str, connector_type: str, connector_class: str) -> list[dict]:
    if connector_type == "sink":
        # ExtractNewRecordState lets a sink reading a Debezium (CDC) topic unwrap the
        # envelope before its own field transforms run.
        keys = ["ExtractNewRecordState", "ExtractField", "ReplaceField", "InsertField", "MaskField", "TimestampConverter", "RegexRouter"]
    elif category == "database_cdc":
        keys = list(SMT_LIB.keys())  # CDC sources support the full SMT set
    elif category == "database_jdbc":
        keys = ["ValueToKey", "InsertField", "ReplaceField", "MaskField", "TimestampConverter", "RegexRouter"]
    elif category == "file":
        keys = ["ReplaceField", "InsertField", "MaskField", "RegexRouter", "Flatten"]
    elif category == "api":
        keys = ["HoistField", "InsertField", "ReplaceField", "RegexRouter", "ExtractField"]
    else:
        keys = ["ReplaceField", "InsertField", "MaskField", "RegexRouter"]
    return [{"type": k, "scope": SMT_LIB[k]["scope"], "description": SMT_LIB[k]["description"],
             "params": SMT_LIB[k]["params"]} for k in keys]


def _seed_rows() -> list[dict]:
    rows = [{**_BASE, **t, "supported_transforms": _transforms_for(t["category"], t["connector_type"], t["connector_class"])}
            for t in TEMPLATE_SEED]
    for row in rows:
        # Kafka Connect gives only SINK connectors a dead-letter queue (app/core/error_policies.py), so a source
        # template must not be seeded as supporting one whatever the table above says.
        if row["connector_type"] != "sink":
            row["supports_dlq"] = False
    return rows


async def init_template_catalog() -> None:
    """Ensure the dc_connector_templates table exists and is seeded."""
    last_err = None
    for _attempt in range(1, 16):
        try:
            async with engine.begin() as conn:
                await conn.run_sync(Base.metadata.create_all)
            break
        except Exception as exc:  # DB not ready yet
            last_err = exc
            await asyncio.sleep(2)
    else:
        logger.error("template_catalog.db_unavailable", error=str(last_err))
        raise RuntimeError(
            "Connector-template catalog database is unreachable; refusing to "
            "start without a working template catalog."
        ) from last_err

    async with AsyncSessionLocal() as session:
        # 1. Seed the default organization first (required for audit logs/connections)
        org = await session.scalar(select(Organization).where(Organization.org_id == "org_1001"))
        if not org:
            session.add(Organization(org_id="org_1001", name="Default Organization", status="active"))
            await session.commit()
            logger.info("template_catalog.seeded_default_org")

        # 2. Seed the connector templates
        count = await session.scalar(select(func.count()).select_from(ConnectorTemplate))
        if not count:
            rows = [ConnectorTemplate(**r) for r in _seed_rows()]
            session.add_all(rows)
            await session.flush()
            # Every template's first revision — see app/services/catalog_revisions.py.
            for row in rows:
                await create_revision(session, row)
            await session.commit()
            logger.info("template_catalog.seeded", count=len(TEMPLATE_SEED))
        else:
            # Refresh the (derived, non-user-editable) code-owned fields every startup so
            # SMT metadata changes (new per-field `params`) and re-qualified plugin/version
            # compatibility data always propagate to existing rows. A template with no
            # current_revision_id yet (it predates revisioning, or was inserted by hand) is
            # backfilled with its first revision here too. Note this means a platform admin's
            # own PUT edit to one of these fields is overwritten back to the seed value on
            # the next restart — same as it already was for supported_transforms — since
            # this table is meant to be qualified in code/CI, not hand-edited in production.
            refreshable_fields = (
                # Runtime design: the worker pool a connector runs in is part of the code-owned qualification record too —
                # every sink in the sink pool, never a source there (app/core/connect_pools.py).
                "runtime_pool_type",
                "supported_transforms",
                "connector_plugin",
                "connector_version",
                "supported_kafka_connect_versions",
                "supported_source_versions",
                "config_schema_version",
                "transform_compatibility",
                "migration_notes",
                # FE-BUG-23: without these, a DB already seeded before this
                # field existed would keep every template's old (empty/True)
                # defaults forever — refreshing them is how an already-running
                # deployment actually picks up the curated per-template values
                # below, not just a fresh install.
                "supported_modes",
                "supports_dlq",
                "supports_schema_discovery",
            )
            expected = {r["id"]: r for r in _seed_rows()}
            existing_rows = (await session.execute(select(ConnectorTemplate))).scalars().all()
            existing_ids = {row.id for row in existing_rows}
            refreshed = 0
            for row in existing_rows:
                want = expected.get(row.id)
                changed = False
                if want is not None:
                    for field in refreshable_fields:
                        if getattr(row, field) != want[field]:
                            setattr(row, field, want[field])
                            changed = True
                if row.current_revision_id is None:
                    changed = True
                if changed:
                    await create_revision(session, row)
                    refreshed += 1

            # A template added to TEMPLATE_SEED after the catalog was first seeded
            # (the common case: shipping a new connector template in a later
            # release) has no row yet — the refresh loop above only ever touches
            # rows that already exist, so without this it would silently never
            # appear no matter how many times the app restarts.
            new_rows = [ConnectorTemplate(**r) for r in _seed_rows() if r["id"] not in existing_ids]
            if new_rows:
                session.add_all(new_rows)
                await session.flush()
                for row in new_rows:
                    await create_revision(session, row)

            if refreshed or new_rows:
                await session.commit()
                logger.info("template_catalog.transforms_refreshed", count=refreshed, added=len(new_rows))

        count = await session.scalar(select(func.count()).select_from(ConnectorTemplate))
    logger.info("template_catalog.ready", count=count)
